// UI Layer for OpenClaw Linux Desktop App// Handles main window, chat interface, tray, notificationsuse gtk4::prelude::*;use gtk4::{Application, ApplicationWindow, Box, Orientation, Entry, Button, Label, ScrolledWindow};use notify_rust::Notification;pub fn launch_ui(app: &Application) {    // Main window    let window = ApplicationWindow::builder()        .application(app)        .title("OpenClaw Linux Agent")        .default_width(800)        .default_height(600)        .build();    // Chat interface    let vbox = Box::new(Orientation::Vertical, 8);    let chat_log = Label::new(Some("Welcome to OpenClaw!"));    let entry = Entry::new();    let send_btn = Button::with_label("Send");    let scrolled = ScrolledWindow::new();    scrolled.set_child(Some(&chat_log));    vbox.append(&scrolled);    vbox.append(&entry);    vbox.append(&send_btn);    window.set_child(Some(&vbox));    // Tray icon and quick actions    use gtk4::{StatusIcon, Menu, MenuItem};    let tray = StatusIcon::new();    tray.set_tooltip_text(Some("OpenClaw Agent"));    tray.set_visible(true);    let menu = Menu::new();    let open_item = MenuItem::with_label("Open App");    let pause_item = MenuItem::with_label("Pause Agent");    let restart_item = MenuItem::with_label("Restart Gateway");    menu.append(&open_item);    menu.append(&pause_item);    menu.append(&restart_item);    menu.show_all();    tray.set_menu(Some(&menu));    // Connect actions to logic    let window_clone = window.clone();    open_item.connect_activate(move |_| {        window_clone.present();    });    pause_item.connect_activate(move |_| {        Notification::new()            .summary("OpenClaw Agent Paused")            .body("The agent is paused.")            .show().ok();        // Actually pause agent logic        crate::gateway_client::stop_gateway();        println!("Agent pause requested: gateway stopped.");    });    restart_item.connect_activate(move |_| {        Notification::new()            .summary("Restarting Gateway")            .body("Gateway is restarting...")            .show().ok();        crate::gateway_client::restart_gateway();    });    // Notifications example    Notification::new()        .summary("OpenClaw Agent Ready")        .body("The agent is running.")        .show().ok();    window.show();}